import java.util.*;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int max = Integer.MIN_VALUE;
        int idx = -1;

        for(int i=0;i<n;i++){
            int v = sc.nextInt();

            if(v > max){
                max = v;
                idx = i;
            }
        }

        System.out.println(idx);
    }
}
